<!-- 渲染工作室：配置后端、质量、媒体及输出预览。 -->
<template>
  <section class="rendering-studio">
    <UiPanelHeader :title="t('renderingStudio')" :description="t('renderingStudioHint')"></UiPanelHeader>
    <UiTabs :aria-label="t('renderingStudio')" :model-value="activeSection" :items="sections.map(item => ({...item,label:t(item.label)}))" @update:model-value="activeSection = sections.find(item => item.id === $event)?.id ?? activeSection" />
    <aside v-if="materialSourceConflict" class="material-source-conflict card" data-audit="material-source-conflict" role="alert"><p>{{ resourceConflictCopy.message }}</p><button @click="loadMaterial(selectedGuid)">{{ resourceConflictCopy.reload }}</button></aside>
    <aside v-if="particleSourceConflict" class="material-source-conflict card" data-audit="particle-source-conflict" role="alert"><p>{{ resourceConflictCopy.message }}</p><button @click="loadParticleGraph(selectedParticleGuid)">{{ resourceConflictCopy.reload }}</button></aside>

    <div v-if="activeSection === 'lighting'" class="section-scroll studio-grid">
      <UiPropertySection :title="t('lighting')" >
        <template #actions><input :aria-label="t('enabled') + ' · ' + t('lighting')" v-model="settings.lightingEnabled" type="checkbox"></template>
        <UiPropertyRow :label="t('ambientIntensity')"><UiSlider v-model.number="settings.ambientIntensity" min="0" max="2" step="0.05" /></UiPropertyRow>
        <UiPropertyRow :label="t('ambientColor')"><input type="color" :value="hex(settings.ambientColor)" @input="setColor(settings.ambientColor, $event)"></UiPropertyRow>
        <UiPropertyRow :label="t('shadowQuality')"><select v-model="settings.shadowQuality"><option>Off</option><option>Hard</option><option>Soft</option><option>Ultra</option></select></UiPropertyRow>
        <p>{{ t('lightingWorkflowHint') }}</p>
      </UiPropertySection>
      <UiPropertySection :title="t('lightingCapabilities')" >
        <template #actions><span :class="capability.path === 'Diagnostic fallback' ? 'warning' : 'good'">{{ capability.path }}</span></template>
        <dl><div><dt>{{ t('rendererBackend') }}</dt><dd>{{ capability.backend }}</dd></div><div><dt>{{ t('maximumTextureSize') }}</dt><dd>{{ capability.maximumTextureSize || 'n/a' }}</dd></div><div><dt>{{ t('normalMaps') }}</dt><dd>{{ capability.backend === 'WebGL2' ? t('supported') : t('fallback') }}</dd></div><div><dt>{{ t('contextRecovery') }}</dt><dd>{{ capability.contextRecovery ? t('supported') : t('unsupported') }}</dd></div></dl>
      </UiPropertySection>
    </div>

    <div v-else-if="activeSection === 'materials'" class="section-scroll material-layout">
      <aside class="card material-list"><header><strong>{{ t('materials') }}</strong><UiButton icon="add" :aria-label="t('newMaterial')" @click="createMaterial" /></header><button v-for="asset in materialAssets" :key="asset.uuid" :class="{ active: selectedGuid === asset.uuid }" @click="selectedGuid = asset.uuid">{{ asset.name }}</button><p v-if="!materialAssets.length">{{ t('noMaterials') }}</p></aside>
      <main class="card material-properties">
        <header><strong>{{ material.name }}</strong><button class="primary" :disabled="!selectedGuid || hasErrors" @click="saveMaterial">{{ t('validateAndSave') }}</button></header>
        <div class="property-grid">
          <UiPropertyRow :label="t('parentMaterial')"><select v-model="material.parentMaterial"><option :value="null">{{ t('none') }}</option><option v-for="asset in parentMaterialAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('blendMode')"><select v-model="material.blendMode"><option>Alpha</option><option>Additive</option><option>Multiply</option><option>Screen</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('filterMode')"><select v-model="material.sampling"><option>Linear</option><option>Nearest</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('colorSpace')"><select v-model="material.colorSpace"><option>sRGB</option><option>Linear</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('variant')"><select v-model="material.activeVariant"><option value="">{{ t('default') }}</option><option v-for="(_,name) in material.variants" :key="name" :value="name">{{ name }}</option></select></UiPropertyRow>
          <UiPropertyRow :label="t('colorWrite')"><input v-model="material.writeColor" type="checkbox"></UiPropertyRow>
        </div>
        <section class="typed-uniforms">
          <header><strong>{{ t('typedUniforms') }}</strong><span>{{ material.uniformSchema.length }}</span></header><p v-if="!material.uniformSchema.length">{{ t('noReflectedUniforms') }}</p>
          <UiPropertyRow :label="(field.label)" v-for="field in material.uniformSchema" :key="field.name">
            <input :aria-label="field.label" v-if="field.type === 'toggle'" :checked="Boolean(material.uniforms[field.name])" type="checkbox" @change="setToggle(field.name, $event)">
            <select :aria-label="field.label" v-else-if="field.type === 'texture'" :value="material.textures[field.name] ?? ''" @change="setTexture(field.name, $event)"><option value="">{{ t('none') }}</option><option v-for="asset in imageAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select>
            <select :aria-label="field.label" v-else-if="field.type === 'enum'" :value="Number(material.uniforms[field.name] ?? 0)" @change="setScalar(field.name, $event, true)"><option v-for="(option,index) in field.options ?? []" :key="option" :value="index">{{ option }}</option></select>
            <input :aria-label="field.label" v-else-if="field.type === 'color'" type="color" :value="uniformColor(field.name)" @input="setUniformColor(field.name, $event)">
            <div v-else-if="field.type.startsWith('vector')" class="vector-inputs"><NumericExpressionInput :aria-label="field.label + ' · ' + index" v-for="index in vectorLength(field.type)" :key="index" :step="0.01" :resource-key="'material:' + selectedGuid + ':uniform:' + field.name + ':' + index" :model-value="uniformComponent(field.name,index-1)" @update:model-value="setUniformComponent(field.name,index-1,$event)"></NumericExpressionInput></div>
            <UiSlider :aria-label="field.label" v-else-if="field.type === 'range'" :min="field.minimum" :max="field.maximum" :step="field.step ?? .01" :value="Number(material.uniforms[field.name] ?? 0)" @input="setScalar(field.name,$event)" />
            <NumericExpressionInput :aria-label="field.label" v-else :minimum="field.minimum" :maximum="field.maximum" :step="field.step ?? (field.type === 'integer' ? 1 : .01)" :resource-key="'material:' + selectedGuid + ':uniform:' + field.name" :model-value="Number(material.uniforms[field.name] ?? 0)" @update:model-value="setScalarValue(field.name,$event,field.type === 'integer')"></NumericExpressionInput>
          </UiPropertyRow>
        </section>
      </main>
      <aside class="card preview-card"><header><strong>{{ t('livePreview') }}</strong></header><canvas ref="previewCanvas" width="480" height="280"></canvas><p :class="hasErrors ? 'error' : 'good'">{{ hasErrors ? t('shaderHasErrors') : t('shaderReady') }}</p></aside>
    </div>

    <div v-else-if="activeSection === 'shaders'" class="section-scroll shader-layout">
      <UiPropertySection :title="t('shaderSource')" class="shader-editor"><template #actions><label class="advanced-toggle"><input v-model="advancedMode" type="checkbox">{{ t('advanced') }}</label></template><div class="shader-options"><UiPropertyRow :label="t('sharedIncludes')"><span><label v-for="(_,name) in includeLibrary" :key="name" class="check"><input type="checkbox" :checked="material.includes.includes(name)" @change="toggleInclude(name)">{{ name }}</label></span></UiPropertyRow></div><textarea :aria-label="t('shaderSource')" v-model="material.fragment" spellcheck="false" @input="schedulePreview"></textarea></UiPropertySection>
      <aside class="card shader-side"><canvas ref="shaderPreviewCanvas" width="420" height="240"></canvas><div class="diagnostics" :class="{ error: hasErrors }"><p v-if="!diagnostics.length">{{ t('shaderReady') }}</p><button v-for="item in diagnostics" :key="`${item.line}:${item.message}`" @click="focusShaderLine(item.line)">{{ item.severity.toUpperCase() }} · L{{ item.line }} · {{ item.message }}</button></div><details data-ui-motion-disclosure v-if="advancedMode" open><summary>{{ t('advancedJsonViews') }}</summary><UiPropertyRow :label="(t('uniformsJson'))"><textarea v-model="uniformsJson" :aria-invalid="!parseObject(uniformsJson) || undefined" rows="5" @change="applyUniforms"></textarea><span v-if="!parseObject(uniformsJson)" role="alert">{{ advancedJsonError }}</span></UiPropertyRow><UiPropertyRow :label="(t('texturesJson'))"><textarea v-model="texturesJson" :aria-invalid="!parseObject(texturesJson) || undefined" rows="4" @change="applyTextures"></textarea><span v-if="!parseObject(texturesJson)" role="alert">{{ advancedJsonError }}</span></UiPropertyRow></details></aside>
    </div>

    <div v-else-if="activeSection === 'graph'" class="section-scroll graph-section">
      <div class="graph-toolbar card"><UiPropertyRow :label="t('materialAsset')"><select v-model="selectedGuid"><option v-for="asset in materialAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option></select></UiPropertyRow><button v-if="!material.graph" class="primary" @click="enableMaterialGraph">{{ t('createVisualGraph') }}</button><button :disabled="!selectedGuid || hasErrors" @click="saveMaterial">{{ t('validateAndSave') }}</button></div>
      <MaterialGraphEditor v-if="material.graph" v-model="material.graph" :resource-key="'material:' + selectedGuid" :layers="material.layers" @update:model-value="schedulePreview" />
      <UiPropertySection :title="t('materialLayers')" class="layer-editor"><template #actions><span>{{ material.layers.length }} / 16</span></template><div class="layer-actions"><UiButton icon="add" v-for="kind in layerKinds" :key="kind" :disabled="material.layers.length >= 16" @click="addLayer(kind)">{{ t(`materialLayer${kind}`) }}</UiButton></div><div v-for="(layer,index) in material.layers" :key="layer.id" class="layer-row" :class="{ selected: selectedLayerId === layer.id }"><input :aria-label="t('enabled') + ' · ' + layer.name" v-model="layer.enabled" type="checkbox" @change="schedulePreview"><button class="layer-name" @click="selectedLayerId = layer.id"><strong>{{ layer.name }}</strong></button><select :aria-label="t('blendMode') + ' · ' + layer.name" v-model="layer.blendMode" @change="schedulePreview"><option>Alpha</option><option>Additive</option><option>Multiply</option><option>Screen</option></select><UiSlider :aria-label="t('opacity') + ' · ' + layer.name" v-model.number="layer.opacity" min="0" max="1" step=".05" @input="schedulePreview" /><UiButton icon="up" :aria-label="t('moveUp') + ' · ' + layer.name" @click="moveLayer(index,-1)" /><UiButton icon="down" :aria-label="t('moveDown') + ' · ' + layer.name" @click="moveLayer(index,1)" /><UiButton icon="clear" :aria-label="t('remove') + ' · ' + layer.name" class="danger" @click="removeLayer(index)" /></div><div v-if="selectedLayer" class="layer-details"><UiPropertyRow :label="(t('name'))"><input v-model.trim="selectedLayer.name" maxlength="80" @change="schedulePreview"></UiPropertyRow><UiPropertyRow :label="(t('startColor'))" v-if="selectedLayer.kind !== 'Mask'"><input type="color" :value="unitColorHex(selectedLayer.colorA)" @input="setLayerColor(selectedLayer.colorA,$event)"></UiPropertyRow><UiPropertyRow :label="(t('endColor'))" v-if="selectedLayer.kind === 'Gradient'"><input type="color" :value="unitColorHex(selectedLayer.colorB)" @input="setLayerColor(selectedLayer.colorB,$event)"></UiPropertyRow><UiPropertyRow :label="(t('mask'))" v-if="selectedLayer.kind === 'Mask'"><select v-model="selectedLayer.texture" @change="schedulePreview"><option :value="null">{{ t('none') }}</option><option v-for="asset in imageAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow><UiPropertyRow :label="(t('strength'))" v-if="['Palette','Outline','Distortion'].includes(selectedLayer.kind)"><NumericExpressionInput v-model="selectedLayer.strength" :minimum="0" :maximum="32" :step=".05" @change="schedulePreview" :resource-key="'material:' + selectedGuid + ':layer:' + selectedLayer.id + ':selectedLayer.strength'" /></UiPropertyRow><UiPropertyRow :label="(t('threshold'))" v-if="selectedLayer.kind === 'Dissolve'"><UiSlider v-model.number="selectedLayer.threshold" min="0" max="1" step=".01" @input="schedulePreview" /></UiPropertyRow><UiPropertyRow :label="(t('softness'))" v-if="selectedLayer.kind === 'Dissolve'"><UiSlider v-model.number="selectedLayer.softness" min=".001" max="1" step=".01" @input="schedulePreview" /></UiPropertyRow></div><p v-if="!material.layers.length">{{ t('noMaterialLayers') }}</p><p>{{ materialGraphRecommendation }}</p></UiPropertySection>
    </div>

    <div v-else-if="activeSection === 'particles'" class="section-scroll particle-section">
      <div class="ui-section-list"><UiPropertySection :title="t('particleBudget')" ><template #actions><span :class="particles.budgetExceeded ? 'error' : 'good'">{{ particles.activeParticles }} / {{ particles.budget }}</span></template><UiPropertyRow :label="t('projectParticleBudget')"><NumericExpressionInput v-model="settings.particleBudget" :minimum="100" :maximum="100000" :resource-key="'render:settings.particleBudget'" /></UiPropertyRow><dl><div><dt>{{ t('emitters') }}</dt><dd>{{ particles.emitterCount }}</dd></div><div><dt>{{ t('particleUpdateTime') }}</dt><dd>{{ particles.updateMs.toFixed(2) }} ms</dd></div><div><dt>{{ t('subemitters') }}</dt><dd>{{ particles.subemissions }}</dd></div><div><dt>CPU / GPU</dt><dd>{{ particles.cpuSimulated }} / {{ particles.gpuRendered }}</dd></div></dl><p>{{ t('particleEditorHint') }}</p></UiPropertySection>
      <UiPropertySection :title="t('particleWorkflow')" ><p>{{ t('particleWorkflowDescription') }}</p><UiPropertyRow :label="t('particleSystemAsset')"><select v-model="selectedParticleGuid"><option value="">{{ t('none') }}</option><option v-for="asset in particleAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option></select></UiPropertyRow><div class="capture-compare"><UiButton icon="add" @click="createParticleAsset">{{ t('assetFromEmitter') }}</UiButton><button :disabled="!selectedParticleGuid" @click="saveParticleAsset">{{ t('saveAsset') }}</button><button :disabled="!selectedParticleGuid" @click="applyParticleAsset">{{ t('applyAsset') }}</button></div><button @click="openParticleInspector">{{ t('selectParticleEmitter') }}</button></UiPropertySection></div>
      <ParticleGraphEditor v-model="particleGraph" :backend="capability.backend" :resource-key="'particle:' + selectedParticleGuid" />
      <UiPropertySection :title="t('particleEvents')" class="event-timeline"><template #actions><span>{{ particles.events.length }}</span></template><p v-if="!particles.events.length">{{ t('noParticleEvents') }}</p><span v-for="event in particles.events.slice(0,12)" :key="`${event.time}:${event.emitterUuid}:${event.kind}`">{{ event.kind }} · {{ event.signal }}</span></UiPropertySection>
    </div>

    <div v-else-if="activeSection === 'post'" class="section-scroll post-layout">
      <UiPropertySection :title="t('postProcessPresets')" ><template #actions><input :aria-label="t('enabled') + ' · ' + t('postProcessing')" v-model="settings.postProcessing.enabled" type="checkbox"></template><UiPropertyRow :label="t('activePreset')"><select v-model="settings.postProcessing.activePreset" @change="applyActivePostPreset"><option v-for="preset in settings.postProcessing.presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></UiPropertyRow><div class="property-grid"><UiPropertyRow :label="t('exposure')"><NumericExpressionInput v-model="activePostPreset.exposure" :minimum="-8" :maximum="8" :step=".1" @change="syncPostPreset" :resource-key="'render:preset:' + settings.postProcessing.activePreset + ':activePostPreset.exposure'" /></UiPropertyRow><UiPropertyRow :label="t('contrast')"><NumericExpressionInput v-model="activePostPreset.contrast" :minimum="0" :maximum="4" :step=".05" @change="syncPostPreset" :resource-key="'render:preset:' + settings.postProcessing.activePreset + ':activePostPreset.contrast'" /></UiPropertyRow><UiPropertyRow :label="t('saturation')"><NumericExpressionInput v-model="activePostPreset.saturation" :minimum="0" :maximum="4" :step=".05" @change="syncPostPreset" :resource-key="'render:preset:' + settings.postProcessing.activePreset + ':activePostPreset.saturation'" /></UiPropertyRow><UiPropertyRow :label="t('vignette')"><UiSlider v-model.number="activePostPreset.vignette" min="0" max="1" step=".05" @input="syncPostPreset" /></UiPropertyRow><UiPropertyRow :label="t('bloom')"><UiSlider v-model.number="activePostPreset.bloom" min="0" max="2" step=".05" @input="syncPostPreset" /></UiPropertyRow><UiPropertyRow :label="t('blur')"><UiSlider v-model.number="activePostPreset.blur" min="0" max="16" step=".25" @input="syncPostPreset" /></UiPropertyRow></div><UiButton icon="add" @click="duplicatePostPreset">{{ t('duplicatePreset') }}</UiButton><p>{{ postCost.passes }} {{ t('passes') }} · {{ postCost.estimatedMsAt1080p }} ms @ 1080p · {{ postCost.recommendation }}</p></UiPropertySection>
      <UiPropertySection :title="t('cameraVolumes')" ><template #actions><UiButton icon="add" :aria-label="t('add') + ' · ' + t('cameraVolume')" @click="addPostVolume" /></template><div v-for="volume in settings.postProcessing.volumes" :key="volume.id" class="volume-card"><label><input :aria-label="t('enabled') + ' · ' + volume.name" v-model="volume.enabled" type="checkbox"><strong>{{ volume.name }}</strong></label><UiPropertyRow :label="(t('preset'))"><select v-model="volume.presetId"><option v-for="preset in settings.postProcessing.presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></UiPropertyRow><UiPropertyRow :label="(t('center')) + ' X'"><NumericExpressionInput :aria-label="t('center') + ' X · ' + volume.name" v-model="volume.center.x" :step=".5" :resource-key="'render:volume:' + volume.id + ':volume.center.x'" />Y<NumericExpressionInput :aria-label="t('center') + ' Y · ' + volume.name" v-model="volume.center.y" :step=".5" :resource-key="'render:volume:' + volume.id + ':volume.center.y'" /></UiPropertyRow><UiPropertyRow :label="(t('size')) + ' X'"><NumericExpressionInput :aria-label="t('size') + ' X · ' + volume.name" v-model="volume.size.x" :minimum=".001" :step=".5" :resource-key="'render:volume:' + volume.id + ':volume.size.x'" />Y<NumericExpressionInput :aria-label="t('size') + ' Y · ' + volume.name" v-model="volume.size.y" :minimum=".001" :step=".5" :resource-key="'render:volume:' + volume.id + ':volume.size.y'" /></UiPropertyRow><UiPropertyRow :label="(t('blendDistance'))"><NumericExpressionInput v-model="volume.blendDistance" :minimum="0" :step=".25" :resource-key="'render:volume:' + volume.id + ':volume.blendDistance'" /></UiPropertyRow><UiPropertyRow :label="(t('priority'))"><NumericExpressionInput v-model="volume.priority" :minimum="-1000" :maximum="1000" :resource-key="'render:volume:' + volume.id + ':volume.priority'" /></UiPropertyRow><button class="danger" @click="removePostVolume(volume.id)">{{ t('remove') }}</button></div><p v-if="!settings.postProcessing.volumes.length">{{ t('noCameraVolumes') }}</p></UiPropertySection>
    </div>

    <div v-else-if="activeSection === 'production'" class="section-scroll production-layout">
      <UiPropertySection class="production-summary" :class="`status-${mediaReport.status}`"><header><div><strong>{{ t('productionMedia') }}</strong><small>{{ t('productionMediaHint') }}</small></div><b>{{ t(`mediaStatus_${mediaReport.status}`) }}</b></header><div class="profile-choice"><button :class="{ active: mediaReport.profile === 'Balanced' }" @click="applyMediaProfile('Balanced')">{{ t('balancedProfile') }}</button><button :class="{ active: mediaReport.profile === 'LowEnd' }" @click="applyMediaProfile('LowEnd')">{{ t('lowEndProfile') }}</button></div><p>{{ t('semanticParityHint') }}</p></UiPropertySection>
<!-- 媒体就绪统计过滤回调仅统计状态为 ready 的检查项。 -->      <UiPropertySection :title="t('productionReadiness')" class="readiness-card"><template #actions><span>{{ mediaReport.checks.filter(item=>item.status==='ready').length }} / {{ mediaReport.checks.length }}</span></template><button v-for="item in mediaReport.checks" :key="item.id" :class="['readiness-row',`status-${item.status}`]" @click="focusMediaSubsystem(item.subsystem)"><span><b>{{ t(`mediaCheck_${item.id}`) }}</b><small>{{ item.detail }}</small></span><strong>{{ t(`mediaStatus_${item.status}`) }}</strong></button></UiPropertySection>
      <UiPropertySection :title="t('textureStreaming')" class="streaming-settings">
        <template #actions><input :aria-label="t('enabled') + ' · ' + t('textureStreaming')" v-model="settings.textureStreaming.enabled" type="checkbox" @change="commitTextureStreaming"></template>
        <UiPropertyRow :label="(t('streamingMemoryBudget')) + ' (MiB)'"><NumericExpressionInput data-streaming="memory" v-model="settings.textureStreaming.memoryBudgetMb" :minimum="16" :maximum="GPU_TEXTURE_MEMORY_LIMIT_MB" @change="commitTextureStreaming" :resource-key="'render:settings.textureStreaming.memoryBudgetMb'" /></UiPropertyRow>
        <UiPropertyRow :label="t('idleEvictionFrames')"><NumericExpressionInput data-streaming="idle" v-model="settings.textureStreaming.idleFrames" :minimum="2" :maximum="36000" @change="commitTextureStreaming" :resource-key="'render:settings.textureStreaming.idleFrames'" /></UiPropertyRow>
        <UiPropertyRow :label="t('uploadBudget')"><NumericExpressionInput data-streaming="uploads" v-model="settings.textureStreaming.uploadBudgetPerFrame" :minimum="1" :maximum="4096" @change="commitTextureStreaming" :resource-key="'render:settings.textureStreaming.uploadBudgetPerFrame'" /></UiPropertyRow>
        <UiPropertyRow :label="t('preloadMargin')"><NumericExpressionInput data-streaming="margin" v-model="settings.textureStreaming.preloadMargin" :minimum="1" :maximum="8" :step=".25" @change="commitTextureStreaming" :resource-key="'render:settings.textureStreaming.preloadMargin'" /></UiPropertyRow>
        <dl><div><dt>{{ t('residentTextures') }}</dt><dd>{{ stats.textures }}</dd></div><div><dt>{{ t('textureMemory') }}</dt><dd>{{ (stats.textureMemoryBytes/1048576).toFixed(1) }} MiB</dd></div><div><dt>{{ t('streamingMisses') }}</dt><dd>{{ stats.streamingMisses }}</dd></div><div><dt>{{ t('textureEvictions') }}</dt><dd>{{ stats.textureEvictions }}</dd></div>
          <div><dt>{{ streamingCopy.uploads }}</dt><dd data-streaming-metric="uploads">{{ streamingMetric(streamingStats.textureUploads) }}</dd></div>
          <div><dt>{{ streamingCopy.queue }}</dt><dd data-streaming-metric="queue">{{ streamingMetric(streamingStats.textureUploadQueue) }}</dd></div>
          <div><dt>{{ streamingCopy.queueBytes }}</dt><dd data-streaming-metric="bytes">{{ streamingMetric(streamingStats.textureUploadQueueBytes, true) }}</dd></div>
          <div><dt>{{ streamingCopy.deferred }}</dt><dd data-streaming-metric="deferred">{{ streamingMetric(streamingStats.textureUploadDeferrals) }}</dd></div>
        </dl>
        <p>{{ streamingCopy.cap.replace('{cap}', String(GPU_TEXTURE_MEMORY_LIMIT_MB)) }}</p>
        <p>{{ streamingCopy.enabled }}</p>
        <p data-streaming-preload>{{ authoringState.performanceMode && settings.textureStreaming.enabled ? streamingCopy.preloadOn : streamingCopy.preloadOff }}</p>
        <p v-if="stats.backend !== 'WebGL2'" class="warning">{{ streamingCopy.canvas }}</p>
      </UiPropertySection>
      <UiPropertySection :title="t('deterministicCapture')" class="capture-sequence"><template #actions><span>{{ captureSequence.frames.length }} / {{ captureSequence.maximumFrames }}</span></template><div class="capture-settings"><UiPropertyRow :label="t('frameRate')"><NumericExpressionInput v-model="settings.deterministicCapture.frameRate" :minimum="1" :maximum="240" :resource-key="'render:settings.deterministicCapture.frameRate'" /></UiPropertyRow><UiPropertyRow :label="t('sampleRate')"><NumericExpressionInput v-model="settings.deterministicCapture.sampleRate" :minimum="8000" :maximum="192000" :resource-key="'render:settings.deterministicCapture.sampleRate'" /></UiPropertyRow><UiPropertyRow :label="t('maximumFrames')"><NumericExpressionInput v-model="settings.deterministicCapture.maximumFrames" :minimum="1" :maximum="18000" :resource-key="'render:settings.deterministicCapture.maximumFrames'" /></UiPropertyRow><UiPropertyRow :label="t('captureMemoryBudget')"><NumericExpressionInput v-model="settings.deterministicCapture.memoryBudgetMb" :minimum="16" :maximum="2048" :resource-key="'render:settings.deterministicCapture.memoryBudgetMb'" /></UiPropertyRow><UiPropertyRow :label="t('includeUi')"><input v-model="settings.deterministicCapture.includeUi" type="checkbox"></UiPropertyRow></div><div class="capture-actions"><button v-if="!captureSequence.active" class="primary" @click="beginCaptureSequence">● {{ t('startCapture') }}</button><UiButton icon="stop" v-else class="danger" @click="stopDeterministicCapture()">{{ t('stopCapture') }}</UiButton><button :disabled="captureSequence.active || !captureSequence.frames.length" @click="clearDeterministicCapture">{{ t('clearCapture') }}</button></div><progress :value="captureSequence.capturedBytes" :max="captureSequence.memoryBudgetBytes"></progress><p>{{ (captureSequence.capturedBytes/1048576).toFixed(1) }} / {{ (captureSequence.memoryBudgetBytes/1048576).toFixed(0) }} MB · {{ captureSequence.stoppedReason || t('captureReady') }}</p><div class="capture-frame-links"><a v-for="frame in captureSequence.frames.slice(-12)" :key="frame.index" :href="frame.dataUrl" :download="`nova-${captureSequence.name}-${String(frame.index).padStart(6,'0')}.png`">#{{ frame.index }} · {{ frame.timeSeconds.toFixed(3) }}s · {{ frame.audioSampleStart }}–{{ frame.audioSampleEnd }}</a></div></UiPropertySection>
      <UiPropertySection :title="t('productionIssues')" class="issue-card"><template #actions><span>{{ mediaReport.issues.length }}</span></template><p v-if="!mediaReport.issues.length" class="good">{{ t('productionMediaReady') }}</p><button v-for="item in mediaReport.issues" :key="`${item.code}:${item.message}`" :class="`status-${item.status}`" @click="focusMediaSubsystem(item.subsystem)"><strong>{{ item.code }} · {{ item.subsystem }}</strong><span>{{ item.message }}</span><small>{{ item.fix }}</small></button></UiPropertySection>
    </div>

