      <UiPropertySection :title="t('savedCaptures')" class="capture-list"><div class="capture-compare"><select :aria-label="t('savedCaptures') + ' A'" v-model.number="captureA"><option :value="0">A</option><option v-for="capture in graph.captures" :key="capture.id" :value="capture.id">{{ capture.createdAt }}</option></select><select :aria-label="t('savedCaptures') + ' B'" v-model.number="captureB"><option :value="0">B</option><option v-for="capture in graph.captures" :key="capture.id" :value="capture.id">{{ capture.createdAt }}</option></select><button :disabled="!captureA || !captureB || captureA === captureB" @click="compareCaptures">{{ t('compareCaptures') }}</button></div><p v-if="lastDifference !== null">{{ t('pixelDifference') }}: {{ (lastDifference * 100).toFixed(4) }}%</p><a v-for="capture in graph.captures" :key="capture.id" :href="capture.dataUrl" :download="`nova-frame-${capture.id}.png`">{{ capture.createdAt }} · {{ capture.width }}×{{ capture.height }}</a></UiPropertySection>
