?? '—' }} / {{ streamingStats.antiAliasingSamples ?? '—' }}</p><p>{{ outputCopy.hint }}</p><button class="secondary-action" data-audit="qualification-help" @click="openProductionManual(preferencesState.locale)">{{ t('documentation') }}</button><p>{{ t('qualityPresetHint') }}</p></UiPropertySection>
      <UiPropertySection :title="t('qualityVolumes')" class="quality-volumes"><template #actions><UiButton icon="add" :aria-label="t('add') + ' · ' + t('qualityVolume')" :disabled="settings.qualityVolumes.length>=64" @click="addQualityVolume" /></template><p>{{ t('qualityVolumeHint') }}</p><div v-for="volume in settings.qualityVolumes" :key="volume.id" class="volume-card"><header><input :aria-label="t('enabled') + ' · ' + volume.name" v-model="volume.enabled" type="checkbox"><input :aria-label="t('qualityVolume') + ' · ' + t('name')" v-model.trim="volume.name" maxlength="80"><UiButton icon="clear" :aria-label="t('remove') + ' · ' + volume.name" @click="removeQualityVolume(volume.id)" /></header><UiPropertyRow :label="t('qualityPreset')"><select v-model="volume.preset"><option v-for="preset in qualityPresets" :key="preset">{{ preset }}</option></select></UiPropertyRow><UiPropertyRow :label="t('priority')"><NumericExpressionInput v-model="volume.priority" :minimum="-1000" :maximum="1000" :resource-key="'render:volume:' + volume.id + ':volume.priority'" /></UiPropertyRow><UiPropertyRow :label="(t('center')) + ' X/Y'"><span class="pair"><NumericExpressionInput :aria-label="t('center') + ' X · ' + volume.name" v-model="volume.center.x" :resource-key="'render:volume:' + volume.id + ':volume.center.x'" /><NumericExpressionInput :aria-label="t('center') + ' Y · ' + volume.name" v-model="volume.center.y" :resource-key="'render:volume:' + volume.id + ':volume.center.y'" /></span></UiPropertyRow><UiPropertyRow :label="(t('size')) + ' W/H'"><span class="pair"><NumericExpressionInput :aria-label="t('size') + ' X · ' + volume.name" v-model="volume.size.x" :minimum=".001" :resource-key="'render:volume:' + volume.id + ':volume.size.x'" /><NumericExpressionInput :aria-label="t('size') + ' Y · ' + volume.name" v-model="volume.size.y" :minimum=".001" :resource-key="'render:volume:' + volume.id + ':volume.size.y'" /></span></UiPropertyRow></div><p v-if="!settings.qualityVolumes.length">{{ t('noQualityVolumes') }}</p></UiPropertySection>
      <UiPropertySection :title="t('projectRenderBudgets')" ><UiPropertyRow :label="t('drawCalls')"><NumericExpressionInput v-model="settings.budgets.drawCalls" :minimum="1" :resource-key="'render:settings.budgets.drawCalls'" /></UiPropertyRow><UiPropertyRow :label="(t('textureMemory')) + ' (MB)'"><NumericExpressionInput v-model="settings.budgets.textureMemoryMb" :minimum="1" :resource-key="'render:settings.budgets.textureMemoryMb'" /></UiPropertyRow><UiPropertyRow label="Overdraw"><NumericExpressionInput v-model="settings.budgets.overdraw" :minimum="1" :step=".25" :resource-key="'render:settings.budgets.overdraw'" /></UiPropertyRow><UiPropertyRow :label="(t('gpuFrame')) + ' (ms)'"><NumericExpressionInput v-model="settings.budgets.gpuMs" :minimum=".1" :step=".1" :resource-key="'render:settings.budgets.gpuMs'" /></UiPropertyRow><UiPropertyRow :label="(t('particles')) + ' (ms)'"><NumericExpressionInput v-model="settings.budgets.particleMs" :minimum=".05" :step=".05" :resource-key="'render:settings.budgets.particleMs'" /></UiPropertyRow></UiPropertySection>
      <UiPropertySection :title="t('postProcessing')" v-if="capability.backend === 'WebGL2'" ><template #actions><input :aria-label="t('enabled') + ' · ' + t('postProcessing')" v-model="settings.postProcessing.enabled" type="checkbox"></template><UiPropertyRow :label="t('postMaterial')"><select v-model="activePostPreset.userMaterial" @change="syncPostPreset"><option :value="null">{{ t('none') }}</option><option v-for="asset in materialAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></UiPropertyRow><UiPropertyRow :label="t('exposure')"><NumericExpressionInput v-model="activePostPreset.exposure" :minimum="-8" :maximum="8" :step="0.1" @change="syncPostPreset" :resource-key="'render:preset:' + settings.postProcessing.activePreset + ':activePostPreset.exposure'" /></UiPropertyRow><UiPropertyRow :label="t('contrast')"><NumericExpressionInput v-model="activePostPreset.contrast" :minimum="0" :maximum="4" :step="0.05" @change="syncPostPreset" :resource-key="'render:preset:' + settings.postProcessing.activePreset + ':activePostPreset.contrast'" /></UiPropertyRow><UiPropertyRow :label="t('saturation')"><NumericExpressionInput v-model="activePostPreset.saturation" :minimum="0" :maximum="4" :step="0.05" @change="syncPostPreset" :resource-key="'render:preset:' + settings.postProcessing.activePreset + ':activePostPreset.saturation'" /></UiPropertyRow><UiPropertyRow :label="t('vignette')"><UiSlider v-model.number="activePostPreset.vignette" min="0" max="1" step="0.05" @input="syncPostPreset" /></UiPropertyRow><UiPropertyRow :label="t('bloom')"><UiSlider v-model.number="activePostPreset.bloom" min="0" max="2" step="0.05" @input="syncPostPreset" /></UiPropertyRow><UiPropertyRow :label="t('blur')"><UiSlider v-model.number="activePostPreset.blur" min="0" max="16" step="0.25" @input="syncPostPreset" /></UiPropertyRow></UiPropertySection>
      <UiPropertySection v-else class="warning-card"><strong>{{ t('fallbackRendererActive') }}</strong><p>{{ t('fallbackRendererDescription') }}</p></UiPropertySection>
    </div>
  </section>
</template>

<script setup lang="ts">
import { settleEditorDrafts } from '../editor/pendingDrafts'
import NumericExpressionInput from './NumericExpressionInput.vue'
import { openProductionManual } from '../runtime/openManual'
import { computed, nextTick, onActivated, onDeactivated, onBeforeUnmount, ref, watch } from 'vue'
import { projectSessionState } from '../projects/projectSession'
import { clearStudioDraft, readStudioDraft, registerStudioDraftOwner, retainStudioDraft, type StudioDraftCandidate, type StudioDraftRecord } from '../editor/studioDraftRetention'
import { assetReference, assetState, createTextAsset, readTextAsset, updateTextAsset } from '../assets/AssetDatabase'
import { t } from '../i18n'
import { preferencesState } from '../store/preferences'
import { authoringState } from '../editor/authoring2d'
import { OUTPUT_QUALITY_COPY } from '../renderer/outputQuality20'
import { renderSettingsCopy } from '../renderer/renderSettingsCopy'
import type { RendererStats } from '../renderer/types'
import { MATERIAL_INCLUDE_LIBRARY, analyzeMaterialShader, defaultMaterial, normalizeMaterial, renderMaterialPreview, resolvedMaterialFragment, serializeMaterial, type Material2DResource, type MaterialUniformType, type ShaderDiagnostic } from '../renderer/materials'
import { defaultMaterialGraph, defaultMaterialLayer, materialCapabilityPreview, validateMaterialGraph, type MaterialLayerKind } from '../renderer/materialGraph'
import { defaultParticleGraph, normalizeParticleGraph, particleGraphValues, type ParticleGraphDocument } from '../renderer/particleGraph'
import { activeRenderQuality as activeQuality, applyQualityPreset, estimatePostProcessCost, GPU_TEXTURE_MEMORY_LIMIT_MB, normalizeTextureStreamingSettings, renderingSettings as settings, updateActivePostProcess, type RenderQualityPreset } from '../renderer/renderSettings'
import { clearDeterministicCapture, compareRenderCaptures, renderGraphState as graph, requestRenderCapture, startDeterministicCapture, stopDeterministicCapture } from '../renderer/renderGraph'
import { atlasPreviews, importPreviews, renderRecommendations } from '../renderer/renderOptimization'
import { queryRendererCapabilities, rendererCapabilityState as capabilityState, requestRendererReset } from '../renderer/capabilities'
import { particleDiagnostics as particles } from '../runtime/particles'
import { buildMediaProductionReport, type MediaProductionProfile } from '../runtime/mediaProduction26'
import { editorState } from '../store/editor'
import { physicsState, pushHistory } from '../store/physics'
import { ParticleEmitter2D, copyComponentValues, pasteComponentValues } from '../world/components'
import MaterialGraphEditor from './MaterialGraphEditor.vue'
import ParticleGraphEditor from './ParticleGraphEditor.vue'

type SectionId = 'lighting' | 'materials' | 'shaders' | 'graph' | 'particles' | 'post' | 'production' | 'diagnostics' | 'quality'
const sections = [{ id: 'lighting' as const, label: 'lighting' }, { id: 'materials' as const, label: 'materials' }, { id: 'shaders' as const, label: 'shaders' }, { id: 'graph' as const, label: 'visualMaterialGraph' }, { id: 'particles' as const, label: 'particles' }, { id: 'post' as const, label: 'postProcessing' }, { id: 'production' as const, label: 'productionMedia' }, { id: 'diagnostics' as const, label: 'diagnostics' }, { id: 'quality' as const, label: 'quality' }]
const activeSection = ref<SectionId>('lighting'), advancedMode = ref(false)
const previewCanvas = ref<HTMLCanvasElement | null>(null), shaderPreviewCanvas = ref<HTMLCanvasElement | null>(null)
const materialAssets = computed(/** 筛选材质资源供编辑。 */ () => assetState.records.filter(/* 比较 asset.assetType 与 'material'，返回严格相等的判断结果。 */ asset => asset.assetType === 'material')), imageAssets = computed(/** 筛选图片资源供纹理绑定。 */ () => assetState.records.filter(/* 比较 asset.assetType 与 'image'，返回严格相等的判断结果。 */ asset => asset.assetType === 'image'))
const particleAssets = computed(/** 筛选粒子系统资源。 */ () => assetState.records.filter(/* 比较 asset.assetType 与 'particleSystem'，返回严格相等的判断结果。 */ asset => asset.assetType === 'particleSystem')), selectedParticleGuid = ref('')
const selectedGuid = ref(assetState.selectedGuid && materialAssets.value.some(/* 比较 asset.uuid 与 assetState.selectedGuid，返回严格相等的判断结果。 */ asset => asset.uuid === assetState.selectedGuid) ? assetState.selectedGuid : materialAssets.value[0]?.uuid ?? '')
const parentMaterialAssets = computed(/** 排除当前材质，返回其他材质候选。 */ () => materialAssets.value.filter(/* 比较 asset.uuid 与 selectedGuid.value，返回严格不等的判断结果。 */ asset => asset.uuid !== selectedGuid.value))
const material = ref<Material2DResource>(defaultMaterial()), diagnostics = ref<ShaderDiagnostic[]>([]), selectedLayerId = ref('')
let uniformsJsonBaseline = '{}', texturesJsonBaseline = '{}'
const uniformsJson = ref('{}'), texturesJson = ref('{}'), captureA = ref(0), captureB = ref(0), lastDifference = ref<number | null>(null)
const stats = computed(/* 返回 editorState.rendererStats 的当前值。 */ () => editorState.rendererStats), graphDiagnostics = computed(/* 根据 material.value.graph 的真假，分别返回 validateMaterialGraph(material.value.graph) 或 []。 */ () => material.value.graph ? validateMaterialGraph(material.value.graph) : []), hasErrors = computed(/** 检查着色器或图诊断是否存在错误。 */ () => diagnostics.value.some(/* 比较 item.severity 与 'error'，返回严格相等的判断结果。 */ item => item.severity === 'error') || graphDiagnostics.value.some(/* 比较 item.severity 与 'error'，返回严格相等的判断结果。 */ item => item.severity === 'error'))
const outputCopy = computed(/* 返回 OUTPUT_QUALITY_COPY[preferencesState.locale] 的当前值。 */ () => OUTPUT_QUALITY_COPY[preferencesState.locale])
const streamingCopy = computed(/* 返回 renderSettingsCopy[preferencesState.locale] 的当前值。 */ () => renderSettingsCopy[preferencesState.locale])
const streamingStats = computed(/** 将当前统计视为完整渲染统计供展示。 */ () => stats.value as RendererStats)
/** 仅对 WebGL2 有效有限指标显示数值，字节按 MiB 显示，其他情况显示占位符。 */ function streamingMetric(value: number | undefined, bytes = false): string {
  if (stats.value.backend !== 'WebGL2' || value === undefined || !Number.isFinite(value)) return '—'
  return bytes ? `${(value / 1048576).toFixed(2)} MiB` : String(value)
}
/** 归一化纹理流送配置并记录历史。 */ function commitTextureStreaming(): void {
  Object.assign(settings.textureStreaming, normalizeTextureStreamingSettings(settings.textureStreaming))
  pushHistory('Edit texture streaming')
}
const includeLibrary = MATERIAL_INCLUDE_LIBRARY, qualityPresets: RenderQualityPreset[] = ['Performance', 'Balanced', 'High', 'Ultra', 'PixelArt']
const capability = computed(/* 当 capabilityState.report 为 null 或 undefined 时返回 queryRendererCapabilities(stats.value.backend)，否则保留左侧值。 */ () => capabilityState.report ?? queryRendererCapabilities(stats.value.backend))
const layerKinds: MaterialLayerKind[] = ['Tint', 'Mask', 'Gradient', 'Palette', 'Outline', 'Dissolve', 'Distortion']
const materialGraphCapability = computed(/** 根据材质图、层和当前后端计算能力预览。 */ () => materialCapabilityPreview(material.value.graph ?? defaultMaterialGraph(material.value.target), material.value.layers, capability.value.backend))
const selectedLayer = computed(/** 查找当前选中材质层。 */ () => material.value.layers.find(/* 比较 layer.id 与 selectedLayerId.value，返回严格相等的判断结果。 */ layer => layer.id === selectedLayerId.value) ?? null)
const materialGraphRecommendation = computed(/** 优先提示 Canvas 回退，否则按 GPU 成本显示预算建议。 */ () => materialGraphCapability.value.fallbackNodes.length ? t('canvasMaterialFallback') : materialGraphCapability.value.gpuCost.score > 24 ? t('materialBudgetReduce') : t('materialBudgetGood'))
const particleGraph = ref<ParticleGraphDocument>(defaultParticleGraph())
const activePostPreset = computed(/** 读取当前后处理预设值，缺失回退全局后处理设置。 */ () => settings.postProcessing.presets.find(/* 比较 item.id 与 settings.postProcessing.activePreset，返回严格相等的判断结果。 */ item => item.id === settings.postProcessing.activePreset)?.values ?? settings.postProcessing)
const postCost = computed(/* 调用 estimatePostProcessCost(activePostPreset.value) 并返回调用结果。 */ () => estimatePostProcessCost(activePostPreset.value))
const recommendations = computed(/* 调用 renderRecommendations(stats.value, assetState.records, settings) 并返回调用结果。 */ () => renderRecommendations(stats.value, assetState.records, settings))
const mediaReport = computed(/* 调用 buildMediaProductionReport(assetState.records, physicsState.world.entities, stats.value, physicsState.audioSettings) 并返回调用结果。 */ () => buildMediaProductionReport(assetState.records, physicsState.world.entities, stats.value, physicsState.audioSettings))
const captureSequence = graph.sequence
const lightCount = computed(/* 返回 physicsState.world.entities.filter(entity=>entity.hasComponent('Light2D')).length 的当前值。 */ () => physicsState.world.entities.filter(/* 调用 entity.hasComponent('Light2D') 并返回调用结果。 */ entity=>entity.hasComponent('Light2D')).length), shadowCasterCount = computed(/* 返回 physicsState.world.entities.filter(entity=>entity.hasComponent('ShadowCaster2D')).length 的当前值。 */ () => physicsState.world.entities.filter(/* 调用 entity.hasComponent('ShadowCaster2D') 并返回调用结果。 */ entity=>entity.hasComponent('ShadowCaster2D')).length), passTime = computed(/* 调用 graph.passes.reduce((sum,pass)=>sum+(pass.enabled?pass.durationMs:0),0) 并返回调用结果。 */ () => graph.passes.reduce(/* 计算表达式 sum+(pass.enabled?pass.durationMs:0) 并返回结果，沿用操作数的原有类型规则。 */ (sum,pass)=>sum+(pass.enabled?pass.durationMs:0),0))
const atlasPages = computed(/* 调用 atlasPreviews(assetState.atlasPages) 并返回调用结果。 */ () => atlasPreviews(assetState.atlasPages)), importPreview = computed(/* 调用 importPreviews(assetState.records) 并返回调用结果。 */ () => importPreviews(assetState.records))
let panelActive = true
let timer = 0
onActivated(() => { panelActive = true; schedulePreview() })
onDeactivated(() => { panelActive = false; clearTimeout(timer) })
const draftProjectId = projectSessionState.id
let materialRecord: StudioDraftRecord | null = null, particleRecord: StudioDraftRecord | null = null
/** 材质或高级 JSON 已修改时构造包含原始草稿和基线的恢复候选。 */ function materialDraftCandidate(): StudioDraftCandidate | null {
  return materialRecord && (serializeMaterial(material.value) !== materialBaseline || advancedJsonDirty()) ? {
    record: materialRecord, projectId: draftProjectId, kind: 'material', baseSource: loadedMaterialSource.value,
    source: JSON.stringify({ material: material.value, materialBaseline, uniformsJson: uniformsJson.value, texturesJson: texturesJson.value, uniformsJsonBaseline, texturesJsonBaseline })
  } : null
}
/** 粒子图偏离基线时构造粒子恢复候选。 */ function particleDraftCandidate(): StudioDraftCandidate | null {
  return particleRecord && JSON.stringify(particleGraph.value) !== particleBaseline ? {
    record: particleRecord, projectId: draftProjectId, kind: 'particle', baseSource: loadedParticleSource.value,
    source: JSON.stringify({ graph: particleGraph.value, particleBaseline })
  } : null
}
/** 候选非空时保留工作室恢复草稿。 */ function retainRenderingDraft(candidate: StudioDraftCandidate | null) { if (candidate) retainStudioDraft(candidate) }
/** 切换材质前保留旧草稿，加载目标并在有缓存时恢复高级编辑文本和基线。 */ function openMaterialDraft(guid: string) {
  retainRenderingDraft(materialDraftCandidate())
  const record = materialAssets.value.find(/* 比较 asset.uuid 与 guid，返回严格相等的判断结果。 */ asset => asset.uuid === guid)
  const retained = record && readStudioDraft(record, draftProjectId, 'material', readTextAsset(guid))
  loadMaterial(guid)
  if (retained) {
    const draft = JSON.parse(retained.entry.source)
    material.value = draft.material; materialBaseline = draft.materialBaseline
