/** 将低端或其他媒体配置映射至性能或均衡质量档并记录历史。 */ function applyMediaProfile(profile: MediaProductionProfile) { applyQualityPreset(profile === 'LowEnd' ? 'Performance' : 'Balanced'); pushHistory(`Apply ${profile} production-media profile`, 'project:rendering') }
/** 按当前确定性捕获设置启动 cinematic 序列。 */ function beginCaptureSequence() { startDeterministicCapture({ name: 'cinematic', ...settings.deterministicCapture }) }
/** 渲染问题进入诊断栏目，动画或电影问题切到动画工作区，音频问题进入界面工作区并显示指引。 */ function focusMediaSubsystem(subsystem: 'Rendering' | 'Animation' | 'Audio' | 'Cinematic') { if (subsystem === 'Rendering') activeSection.value = 'diagnostics'; else { editorState.activeWorkspace = subsystem === 'Animation' || subsystem === 'Cinematic' ? 'animation' : 'ui'; editorState.currentPage = 'scene'; editorState.statusText = subsystem === 'Audio' ? t('openAudioWorkspaceHint') : t('openAnimationWorkspace') } }
const unregisterMaterialDraft = registerStudioDraftOwner({ read: materialDraftCandidate, discard: /* 调用 loadMaterial(selectedGuid.value) 并返回调用结果。 */ () => loadMaterial(selectedGuid.value) })
const unregisterParticleDraft = registerStudioDraftOwner({ read: particleDraftCandidate, discard: /* 调用 loadParticleGraph(selectedParticleGuid.value) 并返回调用结果。 */ () => loadParticleGraph(selectedParticleGuid.value) })
onBeforeUnmount(/** 卸载时保留材质和粒子恢复草稿、解除保存注册并清除预览计时器。 */ () => {
  retainRenderingDraft(materialDraftCandidate()); retainRenderingDraft(particleDraftCandidate())
  unregisterMaterialDraft(); unregisterParticleDraft(); clearTimeout(timer)
})
</script>

